package net.civeira.phylax.feature.identity.user.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.crypto.KeyRingSecretStorage;

class SecondFactorSeedVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property second factor seed of user ")
  void test_second_factor_seed_v_o_builder() {
    KeyRingSecretStorage service = Mockito.mock(KeyRingSecretStorage.class);
    Mockito.when(service.seal("small", "identity.user.second_factor_seed#owner"))
        .thenReturn("sealed:k0:example");
    Assertions.assertEquals("sealed:k0:example", SecondFactorSeedVO.fromPlain("small")
        .getSecondFactorSeedStored(service, "owner").orElse(null));
    Assertions.assertEquals("****", SecondFactorSeedVO.fromPlain("small").toString());
  }
}
